#include <cstddef>
#include <cstdint>
extern "C" std::int64_t permutation_cipher(const std::int64_t*v,std::size_t n) noexcept {if(!v||n<2||n>74||v[0]<0||v[0]>64)return -1;auto len=std::size_t(v[0]);if(n<len+2)return -1;auto kp=len+1;if(v[kp]<1||v[kp]>8||n!=kp+std::size_t(v[kp])+1)return -1;auto k=std::size_t(v[kp]);bool seen[8]{};for(std::size_t i=0;i<k;i++){auto x=v[kp+1+i];if(x<1||x>std::int64_t(k)||seen[x-1])return -1;seen[x-1]=true;}char text[128],out[128];std::size_t m=0;for(std::size_t i=0;i<len;i++){if(v[i+1]<0||v[i+1]>127)return -1;int c=int(v[i+1]);if(c==32||c==9||c==10||c==11||c==12||c==13)continue;if(c>='a'&&c<='z')c-=32;text[m++]=char(c);}while(m%k)text[m++]='X';std::size_t q=0;for(std::size_t b=0;b<m;b+=k)for(std::size_t j=0;j<k;j++)out[q++]=text[b+std::size_t(v[kp+1+j]-1)];std::uint64_t h=0;for(std::size_t i=0;i<q;i++)h=(h*257u+static_cast<unsigned char>(out[i]))%1000000007u;return std::int64_t(h);}
